/* Run after you edit album-builder-src/album-builder.html:   node album-builder-src/build.js
   It writes api/_lib/album-builder-page.js, which api/album-builder.js serves to signed-in editors only. */
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const html = fs.readFileSync(path.join(__dirname, 'album-builder.html'), 'utf8');
fs.writeFileSync(path.join(root, 'api/_lib/album-builder-page.js'),
  '/* GENERATED by album-builder-src/build.js. Do not edit by hand. */\nmodule.exports = ' + JSON.stringify(html) + ';\n');
console.log('Wrote api/_lib/album-builder-page.js (' + html.length + ' characters)');
